#include <stdio.h>
#define N 10
#define INF 100000000
int main(){int n,c[N][N],dp[1<<N][N],pa[1<<N][N];long long states=0;printf("Delivery locations excluding hub (1..9): ");if(scanf("%d",&n)!=1||n<1||n>=N)return 1;int v=n+1;puts("Enter cost matrix:");for(int i=0;i<v;i++)for(int j=0;j<v;j++)if(scanf("%d",&c[i][j])!=1||c[i][j]<0)return 1;int full=(1<<v)-1;for(int s=0;s<=full;s++)for(int j=0;j<v;j++)dp[s][j]=INF,pa[s][j]=-1;dp[1][0]=0;for(int s=1;s<=full;s++)if(s&1)for(int j=0;j<v;j++)if((s>>j&1)&&dp[s][j]<INF)for(int k=1;k<v;k++)if(!(s>>k&1)){states++;int ns=s|1<<k;if(dp[s][j]+c[j][k]<dp[ns][k])dp[ns][k]=dp[s][j]+c[j][k],pa[ns][k]=j;}int best=INF,last=-1;for(int j=1;j<v;j++)if(dp[full][j]+c[j][0]<best)best=dp[full][j]+c[j][0],last=j;if(last<0){puts("No tour");return 0;}int route[N],z=0,s=full,x=last;while(x>0){route[z++]=x;int y=pa[s][x];s^=1<<x;x=y;}printf("Optimal route Hub -> ");for(int i=z-1;i>=0;i--)printf("%d -> ",route[i]);printf("Hub\nMinimum cost=%d\nTransitions evaluated=%lld\nDP table cells=%d\n",best,states,(1<<v)*v);}
